require_once dirname(__DIR__).'/app/bootstrap.php';require_login();$id=(int)($_GET['id']??$_POST['listing_id']??0);$s=db()->prepare("SELECT id,name,slug,location,address,owner_user_id,verified FROM listings WHERE id=:id AND status='published'");$s->execute([':id'=>$id]);$listing=$s->fetch();if(!$listing){http_response_code(404);exit('Listing not found.');}if(!empty($listing['owner_user_id'])){http_response_code(409);exit('This business already has a verified owner. Contact the site administrator if you believe this is incorrect.');}$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=trim((string)($_POST['business_email']??''));$phone=trim((string)($_POST['business_phone']??''));$message=trim((string)($_POST['message']??''));if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid business email.';if(text_len($message)<20)$errors[]='Please explain your relationship to this business (at least 20 characters).';$check=db()->prepare("SELECT id FROM owner_claims WHERE listing_id=:l AND user_id=:u AND status IN ('pending','approved')");$check->execute([':l'=>$id,':u'=>current_user_id()]);if($check->fetchColumn())$errors[]='You already have a pending or approved claim for this listing.';if(!$errors){db()->prepare("INSERT INTO owner_claims(listing_id,user_id,business_email,business_phone,message) VALUES(:l,:u,:e,:p,:m)")->execute([':l'=>$id,':u'=>current_user_id(),':e'=>$email,':p'=>$phone,':m'=>$message]);db()->prepare("UPDATE users SET role='owner' WHERE id=:id AND role='member'")->execute([':id'=>current_user_id()]);flash('success','Your ownership request has been sent for manual verification.');redirect(app_path('account.php'));}}
$pageTitle='Claim '. $listing['name'];include __DIR__.'/includes/header.php';?>
<main id="main" class="container form-page"><div class="page-intro"><span class="eyebrow">BUSINESS OWNER VERIFICATION</span><h1>Claim <?= h($listing['name']) ?>.</h1><p><?= h($listing['address']?:$listing['location']) ?>. Claims are reviewed by an administrator before owner access is granted.</p></div><?php if($errors): ?><div class="alert alert-error"><ul><?php foreach($errors as $e): ?><li><?= h($e) ?></li><?php endforeach; ?></ul></div><?php endif; ?><form class="form-card studio-fields" method="post"><?= csrf_field() ?><input type="hidden" name="listing_id" value="<?= $id ?>"><label>Business email<input type="email" name="business_email" placeholder="you@business.com"></label><label>Business phone<input name="business_phone" maxlength="30" placeholder="Business contact number"></label><label>Tell us how you are associated with this business<textarea name="message" rows="5" minlength="20" maxlength="1500" required placeholder="Your role, official website, documents you can provide, or other verification details..."></textarea></label><div class="form-footnote"><i class="fa-solid fa-shield-halved"></i> Do not submit passwords, identity numbers or sensitive personal information. The administrator may contact you using independently verified business details.</div><button class="button button-primary">Submit ownership request</button></form></main><?php include __DIR__.'/includes/footer.php';?>
